package com.hmdp.ai.infrastructure.persistence;import com.hmdp.ai.domain.artifact.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.Optional;@Repository public class JdbcArtifactRepository implements ArtifactRepository {private final JdbcTemplate jdbc;public JdbcArtifactRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public Optional<ArtifactRecord>find(String t,String w,String id){return jdbc.query("select id,tenant_id,workspace_id,run_id,name,content_type,object_key,size_bytes,created_by,status from ai_artifact where tenant_id=? and workspace_id=? and id=? and status='ACTIVE' and deleted=0",(rs,row)->new ArtifactRecord(rs.getString("id"),rs.getString("tenant_id"),rs.getString("workspace_id"),rs.getString("run_id"),rs.getString("name"),rs.getString("content_type"),rs.getString("object_key"),rs.getLong("size_bytes"),rs.getString("created_by"),rs.getString("status")),t,w,id).stream().findFirst();}}
